package cn.mop.adapters.backup;
import cn.mop.domain.DomainException;
import cn.mop.adapters.backup.BackupEnvelopeEncryption.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.Test;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
class BackupEnvelopeEncryptionTest {
 static final UUID TENANT=UUID.fromString("79000000-0000-4000-8000-000000000001"),ASSET=UUID.fromString("79000000-0000-4000-8000-000000000002"),RUN=UUID.fromString("79000000-0000-4000-8000-000000000003"),VERSION=UUID.fromString("79000000-0000-4000-8000-000000000004");
 static final Scope SCOPE=new Scope(TENANT,ASSET,RUN,1,VERSION);static final Access ACCESS=new Access(TENANT,UUID.randomUUID(),1);
 static final byte[] WRAPPED="SYNTHETIC-WRAPPED-KEY-NOT-A-KMS-CIPHERTEXT".getBytes(StandardCharsets.US_ASCII),PLAIN="SYNTHETIC router configuration\nhostname example\n".getBytes(StandardCharsets.US_ASCII);
 static final String REF="kms-key-ref:synthetic-vector";
 static byte[] key(){byte[] k=new byte[32];for(int i=0;i<32;i++)k[i]=(byte)i;return k;}
 static String sha(byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}
 static class Provider implements DataKeyProvider{int creates,unwraps;KeyMaterial last;public KeyMaterial create(Access a,Scope s){creates++;return last=new KeyMaterial(REF,WRAPPED,key());}public KeyMaterial unwrap(Access a,Scope s,String ref,byte[] wrapped){unwraps++;return last=new KeyMaterial(ref,wrapped,key());}}
 static class VectorRandom extends SecureRandom{@Override public void nextBytes(byte[] b){for(int i=0;i<b.length;i++)b[i]=(byte)i;}}
 static BackupEnvelopeEncryption cipher(Provider p){return new BackupEnvelopeEncryption(p,(a,s,o)->true,1024,new VectorRandom());}
 static JsonNode vector()throws Exception{Path p=Path.of("../../fixtures/backup-envelope-synthetic-vector-20261021.json");if(!Files.isRegularFile(p))p=Path.of("fixtures/backup-envelope-synthetic-vector-20261021.json");return new ObjectMapper().readTree(Files.readString(p));}
 @Test void matchesIndependentPythonAes256GcmVector()throws Exception{var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,PLAIN);var v=vector();assertEquals(v.path("ciphertext_hex").asText(),HexFormat.of().formatHex(e.ciphertext()));assertEquals(v.path("envelope_hex").asText(),HexFormat.of().formatHex(e.encoded()));assertEquals(v.path("envelope_sha256").asText(),e.sha256());assertTrue(p.last.destroyed());assertFalse(e.storageVerified());assertFalse(e.deviceExecutionAuthorized());assertFalse(e.evidenceAccessGranted());}
 @Test void independentEncodedVectorAuthenticatesAndReturnsExactBytes()throws Exception{var v=vector();var p=new Provider();var c=cipher(p);var e=c.decode(HexFormat.of().parseHex(v.path("envelope_hex").asText()),v.path("envelope_sha256").asText(),SCOPE);assertArrayEquals(PLAIN,c.open(ACCESS,SCOPE,e));assertTrue(p.last.destroyed());assertEquals(1,p.unwraps);}
 @Test void inputsOutputsAndKeysHaveDefensiveOwnership(){var p=new Provider();var c=cipher(p);byte[] input=PLAIN.clone();var e=c.seal(ACCESS,SCOPE,input);assertArrayEquals(PLAIN,input);input[0]^=1;byte[] cipher=e.ciphertext(),nonce=e.nonce(),wrapped=e.wrappedKey();cipher[0]^=1;nonce[0]^=1;wrapped[0]^=1;assertArrayEquals(PLAIN,c.open(ACCESS,SCOPE,e));assertFalse(e.toString().contains("hostname"));assertEquals("BackupKeyMaterial[REDACTED]",p.last.toString());}
 @Test void tamperedCiphertextReturnsNoUnauthenticatedBytes(){var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,PLAIN);var bad=e.ciphertext();bad[0]^=1;var modified=new Envelope(SCOPE,REF,WRAPPED,e.nonce(),bad);var ex=assertThrows(DomainException.class,()->c.open(ACCESS,SCOPE,modified));assertEquals(503,ex.status);assertNull(ex.getCause());assertTrue(p.last.destroyed());}
 @Test void associatedDataBindsVersionRunAssetAndAttempt(){var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,PLAIN);for(Scope s:List.of(new Scope(TENANT,UUID.randomUUID(),RUN,1,VERSION),new Scope(TENANT,ASSET,UUID.randomUUID(),1,VERSION),new Scope(TENANT,ASSET,RUN,2,VERSION),new Scope(TENANT,ASSET,RUN,1,UUID.randomUUID()))){var forged=new Envelope(s,REF,WRAPPED,e.nonce(),e.ciphertext());assertEquals(503,assertThrows(DomainException.class,()->c.open(ACCESS,s,forged)).status);}assertTrue(p.last.destroyed());}
 @Test void changedKeyReferenceOrWrappedBlobCannotAuthenticateEvenWithSameRawKey(){var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,PLAIN);for(var forged:List.of(new Envelope(SCOPE,"kms-key-ref:other",WRAPPED,e.nonce(),e.ciphertext()),new Envelope(SCOPE,REF,new byte[]{1},e.nonce(),e.ciphertext()))){assertEquals(503,assertThrows(DomainException.class,()->c.open(ACCESS,SCOPE,forged)).status);}}
 @Test void tenantAndExpectedScopeMismatchRejectBeforeProvider(){var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,PLAIN);assertEquals(404,assertThrows(DomainException.class,()->c.open(new Access(UUID.randomUUID(),ACCESS.actorId(),1),SCOPE,e)).status);assertEquals(404,assertThrows(DomainException.class,()->c.open(ACCESS,new Scope(TENANT,ASSET,RUN,2,VERSION),e)).status);assertEquals(0,p.unwraps);}
 @Test void authorizationDeniedBeforeAnyKeyAccess(){var p=new Provider();var e=cipher(p).seal(ACCESS,SCOPE,PLAIN);var c=new BackupEnvelopeEncryption(p,(a,s,o)->false,1024);assertEquals(403,assertThrows(DomainException.class,()->c.seal(ACCESS,SCOPE,PLAIN)).status);assertEquals(403,assertThrows(DomainException.class,()->c.open(ACCESS,SCOPE,e)).status);assertEquals(1,p.creates);assertEquals(0,p.unwraps);}
 @Test void revocationAfterEncryptionOrDecryptionReturnsNothingAndDestroysOwnedKey(){for(boolean decrypt:List.of(false,true)){var p=new Provider();var e=cipher(p).seal(ACCESS,SCOPE,PLAIN);var count=new AtomicInteger();var c=new BackupEnvelopeEncryption(p,(a,s,o)->count.incrementAndGet()==1,1024);assertEquals(403,assertThrows(DomainException.class,()->{if(decrypt)c.open(ACCESS,SCOPE,e);else c.seal(ACCESS,SCOPE,PLAIN);}).status);assertTrue(p.last.destroyed());assertEquals(2,count.get());}}
 @Test void providerAndAuthorizationErrorsNeverExposeSensitiveMessages(){var p=new Provider(){@Override public KeyMaterial create(Access a,Scope s){throw new DomainException(500,"SECRET","password=never-expose");}};var c=cipher(p);var ex=assertThrows(DomainException.class,()->c.seal(ACCESS,SCOPE,PLAIN));assertEquals(503,ex.status);assertFalse(ex.getMessage().contains("never-expose"));assertNull(ex.getCause());var other=new BackupEnvelopeEncryption(new Provider(),(a,s,o)->{throw new Exception("token=never-expose");},1024);assertFalse(assertThrows(DomainException.class,()->other.seal(ACCESS,SCOPE,PLAIN)).getMessage().contains("never-expose"));}
 @Test void requiresExplicitProviderAuthorizationAndBoundedLimit(){assertThrows(NullPointerException.class,()->new BackupEnvelopeEncryption(null,(a,s,o)->true,1024));assertThrows(NullPointerException.class,()->new BackupEnvelopeEncryption(new Provider(),null,1024));for(int limit:new int[]{0,-1,BackupEnvelopeEncryption.MAX_PLAINTEXT_BYTES+1})assertThrows(DomainException.class,()->new BackupEnvelopeEncryption(new Provider(),(a,s,o)->true,limit));}
 @Test void wrongKeyLengthNonceReferenceAndWrappedBoundsAreRejected(){for(int size:new int[]{0,16,24,31,33})assertThrows(DomainException.class,()->new KeyMaterial(REF,WRAPPED,new byte[size]));for(String ref:new String[]{"", "https://untrusted/key", "kms-key-ref:bad\n"})assertThrows(DomainException.class,()->new KeyMaterial(ref,WRAPPED,key()));assertThrows(DomainException.class,()->new KeyMaterial(REF,new byte[8193],key()));assertThrows(DomainException.class,()->new Envelope(SCOPE,REF,WRAPPED,new byte[16],new byte[16]));}
 @Test void limitRejectsBeforeAuthorizationAndDoesNotTruncate(){var p=new Provider();var checks=new AtomicInteger();var c=new BackupEnvelopeEncryption(p,(a,s,o)->{checks.incrementAndGet();return true;},1);assertThrows(DomainException.class,()->c.seal(ACCESS,SCOPE,new byte[2]));assertEquals(0,checks.get());assertEquals(0,p.creates);var e=cipher(p).seal(ACCESS,SCOPE,PLAIN);assertThrows(DomainException.class,()->c.open(ACCESS,SCOPE,e));assertEquals(0,p.unwraps);}
 @Test void emptyBytesRemainExactAuthenticatedEmptyNotADeviceSuccess(){var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,new byte[0]);assertEquals(16,e.ciphertext().length);assertArrayEquals(new byte[0],c.open(ACCESS,SCOPE,e));assertFalse(e.storageVerified());}
 @Test void productionConstructorUsesFreshRandomNonces(){var p=new Provider();var c=new BackupEnvelopeEncryption(p,(a,s,o)->true,1024);var a=c.seal(ACCESS,SCOPE,PLAIN);var b=c.seal(ACCESS,SCOPE,PLAIN);assertFalse(Arrays.equals(a.nonce(),b.nonce()));assertArrayEquals(PLAIN,c.open(ACCESS,SCOPE,a));assertArrayEquals(PLAIN,c.open(ACCESS,SCOPE,b));}
 @Test void destroyedMaterialCannotBeReusedAsAKey(){var material=new KeyMaterial(REF,WRAPPED,key());material.close();material.close();assertTrue(material.destroyed());var p=new Provider(){@Override public KeyMaterial create(Access a,Scope s){return material;}};assertEquals(503,assertThrows(DomainException.class,()->cipher(p).seal(ACCESS,SCOPE,PLAIN)).status);}
 @Test void canonicalDecodeRejectsTruncationTrailingBytesBadDigestAndWrongScope()throws Exception{var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,PLAIN);byte[] original=e.encoded();for(byte[] bytes:List.of(Arrays.copyOf(original,original.length-1),Arrays.copyOf(original,original.length+1),new byte[0]))assertThrows(DomainException.class,()->c.decode(bytes,sha(bytes),SCOPE));assertThrows(DomainException.class,()->c.decode(original,"0".repeat(64),SCOPE));assertThrows(DomainException.class,()->c.decode(original,e.sha256(),new Scope(TENANT,ASSET,RUN,2,VERSION)));assertEquals(0,p.unwraps);}
 @Test void recomputingTransportDigestCannotBypassGcmAuthentication()throws Exception{var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,PLAIN);byte[] changed=e.encoded();changed[changed.length-1]^=1;var decoded=c.decode(changed,sha(changed),SCOPE);assertEquals(503,assertThrows(DomainException.class,()->c.open(ACCESS,SCOPE,decoded)).status);}
 @Test void providerMustReturnTheSameWrappedBindingForUnwrap(){var p=new Provider();var e=cipher(p).seal(ACCESS,SCOPE,PLAIN);var wrong=new Provider(){@Override public KeyMaterial unwrap(Access a,Scope s,String ref,byte[] w){return last=new KeyMaterial("kms-key-ref:other",w,key());}};assertEquals(503,assertThrows(DomainException.class,()->cipher(wrong).open(ACCESS,SCOPE,e)).status);assertTrue(wrong.last.destroyed());}
 @Test void encodedLengthsAreBoundedBeforeAllocationAndNeverTruncated()throws Exception{var c=cipher(new Provider());var e=c.seal(ACCESS,SCOPE,PLAIN);byte[] original=e.encoded();int headerLength=original.length-12-4-e.ciphertext().length,wrappedLengthOffset=headerLength-e.wrappedKey().length-4;for(int size:new int[]{-1,0,8193,Integer.MAX_VALUE}){byte[] changed=original.clone();java.nio.ByteBuffer.wrap(changed).putInt(wrappedLengthOffset,size);assertThrows(DomainException.class,()->c.decode(changed,sha(changed),SCOPE));}for(int size:new int[]{-1,0,15,1041,Integer.MAX_VALUE}){byte[] changed=original.clone();java.nio.ByteBuffer.wrap(changed).putInt(headerLength+12,size);assertThrows(DomainException.class,()->c.decode(changed,sha(changed),SCOPE));}}
 @Test void modifiedNonceAndAlgorithmCannotFallBackToUnauthenticatedDecryption()throws Exception{var p=new Provider();var c=cipher(p);var e=c.seal(ACCESS,SCOPE,PLAIN);byte[] nonce=e.nonce();nonce[0]^=1;assertEquals(503,assertThrows(DomainException.class,()->c.open(ACCESS,SCOPE,new Envelope(SCOPE,REF,WRAPPED,nonce,e.ciphertext()))).status);byte[] bytes=e.encoded();bytes[2+BackupEnvelopeEncryption.FORMAT.length()+2]^=1;assertThrows(DomainException.class,()->c.decode(bytes,sha(bytes),SCOPE));}

 @Test void rawKeyCannotBeMistakenForItsWrappedRepresentation(){assertThrows(DomainException.class,()->new KeyMaterial(REF,key(),key()));}

}
